}

/** The dashboard's filters; each joins the widgets it targets. */
export function DashboardFilterBar({
  editing,
  filters,
  label,
  locale,
  onAddFilter,
  onChange,
  onRemove,
  tables,
  translate,
}: {
  editing: boolean;
  filters: DashboardFilter[];
  label: DashboardLabel;
  locale: string;
  translate: DashboardTranslate;
  onAddFilter: () => void;
  onChange: (
    filterId: string,
    value: DashboardDateRange | string[] | undefined
  ) => void;
  onRemove: (filterId: string) => void;
  tables: Record<string, DashboardTableInfo>;
}) {
  if (!(filters.length || editing)) {
    return null;
  }
  return (
    <section
      aria-label={label("filters")}
      className={cn(
        "flex flex-wrap",
        editing
          ? "items-end gap-x-6 gap-y-3 rounded-xl border bg-muted/40 p-3"
          : "items-center gap-2"
      )}
      data-dashboard-filters=""
    >
      {filters.map((filter) => (
        <DashboardFilterControl
          editing={editing}
          filter={filter}
          key={filter.id}
          label={label}
          locale={locale}
          onChange={(value) => onChange(filter.id, value)}
          onRemove={() => onRemove(filter.id)}
          tables={tables}
          translate={translate}
        />
      ))}
