}

/**
 * Fit widgets (`settings.overflow: "fit"`, the default) show the records that
 * fit their height and nothing scrolls. Shared by the React and Vue editions:
 * both mark each record of a table, list, gallery, board and feed with
 * `data-row-id`, board lanes with `data-kanban-lane` and the board with
 * `data-kanban-board`. Hidden records carry `data-dashboard-overflow`, which
 * `dashboard-grid.css` hides.
 */

const RECORD = "[data-row-id]";
const BOARD = "[data-kanban-board]";
const LANE = "[data-kanban-lane]";
export const DASHBOARD_OVERFLOW_ATTRIBUTE = "data-dashboard-overflow";
const HIDDEN = `[${DASHBOARD_OVERFLOW_ATTRIBUTE}]`;
/** Sub-pixel rounding is not overflow. */
const TOLERANCE = 1;
/**
 * Space a view may keep below its last record (paddings and borders of its
 * list, board or feed). Overflow left once every record ends this far above
 * the bottom is not the records' doing: the widget clips it.
 */
const TRAILING_SPACE = 40;
/** Columns a table keeps, however narrow the widget. */
const MIN_COLUMNS = 2;

export interface DashboardFitResult {
  /** Records shown. */
  shown: number;
  /** Records loaded but hidden. */
  hidden: number;
}

const hide = (element: Element) =>
  element.setAttribute(DASHBOARD_OVERFLOW_ATTRIBUTE, "");
const isShown = (element: Element) =>
  !element.closest(HIDDEN) && element.getClientRects().length > 0;
/** Records of the container, the outer one only when a record holds another (a feed post in its item). */
const recordsOf = (container: HTMLElement) =>
  [...container.querySelectorAll(RECORD)].filter(
    (record) => !record.parentElement?.closest(RECORD)
  );

/** Lanes that do not fit the width are hidden from the right; one always stays. */
function fitLanes(container: HTMLElement) {
  for (const board of container.querySelectorAll<HTMLElement>(BOARD)) {
    const lanes = [...board.querySelectorAll(LANE)];
    let shown = lanes.length;
    while (shown > 1 && board.scrollWidth > board.clientWidth + TOLERANCE) {
      shown -= 1;
      const lane = lanes[shown];
      if (lane) {
        hide(lane);
      }
    }
  }
}

/** Table columns that do not fit the width are hidden from the right. */
function fitColumns(container: HTMLElement) {
  for (const table of container.querySelectorAll("table")) {
    const frame = table.parentElement ?? container;
    const rows = [...table.rows];
    const width = Math.max(0, ...rows.map((row) => row.cells.length));
    let shown = width;
    while (
      shown > MIN_COLUMNS &&
      table.getBoundingClientRect().width > frame.clientWidth + TOLERANCE
    ) {
      shown -= 1;
      for (const row of rows) {
        const cell = row.cells.length === width ? row.cells[shown] : undefined;
        if (cell) {
          hide(cell);
        }
      }
    }
  }
}

/** The shown record reaching lowest (the last one in reading order on ties). */
function lowestRecord(records: readonly Element[]) {
  let lowest: { record: Element; bottom: number } | undefined;
  for (const record of records) {
    const bottom = record.getBoundingClientRect().bottom;
    if (!lowest || bottom >= lowest.bottom) {
      lowest = { record, bottom };
    }
  }
  return lowest;
}

/**
 * Records hide from the lowest up while the content overflows, which also
 * accounts for the paddings and borders below them. Records starting below
 * the visible area go first, at once. The first line always stays (the
 * first record, a gallery's first row of cards, each lane's first card).
 */
function fitRecords(container: HTMLElement) {
  const overflows = () =>
    container.scrollHeight > container.clientHeight + TOLERANCE;
  if (!overflows()) {
    return;
  }
  const records = recordsOf(container).filter(isShown);
  const firstTop = records.at(0)?.getBoundingClientRect().top ?? 0;
  const kept = new Set(
    records.filter(
      (record) =>
        Math.abs(record.getBoundingClientRect().top - firstTop) <= TOLERANCE
    )
  );
  const box = container.getBoundingClientRect();
  const bottom = box.top + container.clientTop + container.clientHeight;
  let shown = records.filter((record) => !kept.has(record));
  for (const record of shown) {
    if (record.getBoundingClientRect().top >= bottom) {
      hide(record);
    }
  }
  shown = shown.filter(isShown);
  while (shown.length && overflows()) {
    const lowest = lowestRecord(shown);
    if (!lowest || lowest.bottom <= bottom - TRAILING_SPACE) {
      return;
    }
    hide(lowest.record);
    shown = shown.filter((record) => record !== lowest.record);
  }
}

/**
 * Hides the records, lanes and columns that do not fit in `container` (an
 * element that clips, with a definite height) and counts the records left.
 */
export function fitDashboardRecords(
  container: HTMLElement
): DashboardFitResult {
  for (const element of container.querySelectorAll(HIDDEN)) {
    element.removeAttribute(DASHBOARD_OVERFLOW_ATTRIBUTE);
  }
  fitLanes(container);
  fitColumns(container);
  fitRecords(container);
  const records = recordsOf(container);
  const shown = records.filter(isShown).length;
  return { shown, hidden: records.length - shown };
}

/**
 * Fits `container` now and again when it resizes, its content changes,
 * images load or fonts arrive; `onFit` hears each new result.
 */
export function observeDashboardFit(
  container: HTMLElement,
  onFit: (result: DashboardFitResult) => void
): () => void {
  const view = container.ownerDocument.defaultView;
  let disposed = false;
  let last = "";
  const refit = () => {
    if (disposed || !container.isConnected) {
      return;
    }
    const result = fitDashboardRecords(container);
    const key = `${result.shown}:${result.hidden}`;
    if (key !== last) {
      last = key;
      onFit(result);
    }
  };
  // Both run before paint, so records never flash in before hiding.
  const resize =
    typeof view?.ResizeObserver === "function"
      ? new view.ResizeObserver(refit)
      : undefined;
  resize?.observe(container);
  const mutation =
    typeof view?.MutationObserver === "function"
      ? new view.MutationObserver(refit)
      : undefined;
  mutation?.observe(container, {
    childList: true,
    subtree: true,
    characterData: true,
  });
  container.addEventListener("load", refit, true);
  container.ownerDocument.fonts?.ready.then(refit).catch(() => undefined);
  refit();
  return () => {
    disposed = true;
    resize?.disconnect();
    mutation?.disconnect();
    container.removeEventListener("load", refit, true);
  };
}

/**
 * The desktop grid, driven by gridstack.js in both editions. Loaded on demand
 * (`import("./dashboard-grid-engine")`) with gridstack's styles, so neither
 * the table nor phones download it. The framework renders the items
 * (`.grid-stack-item[gs-id]`); this controller hands them to gridstack and
 * reports the positions users drag and resize to.
 */
import "gridstack/dist/gridstack.min.css";
import { type GridItemHTMLElement, GridStack } from "gridstack";
import {
  DASHBOARD_COLUMNS,
  DASHBOARD_MARGIN,
  DASHBOARD_ROW_HEIGHT,
  type DashboardLayoutItem,
} from "./dashboard-layout";

export interface DashboardGridController {
  /** Hands new items to gridstack, drops removed ones and applies `layout`. */
  sync: (layout: readonly DashboardLayoutItem[], editing: boolean) => void;
  destroy: () => void;
}

const itemElements = (element: HTMLElement): GridItemHTMLElement[] =>
  [...element.children].filter(
    (child): child is GridItemHTMLElement =>
      child instanceof HTMLElement &&
      child.classList.contains("grid-stack-item")
  );

const place = (item: DashboardLayoutItem) => ({
  x: item.x,
  y: item.y,
  w: item.w,
  h: item.h,
});

const differs = (
  element: GridItemHTMLElement,
  item: DashboardLayoutItem
): boolean => {
  const node = element.gridstackNode;
  return (
    !node ||
    node.x !== item.x ||
    node.y !== item.y ||
    node.w !== item.w ||
    node.h !== item.h
  );
};

/** Starts gridstack on the grid element; `onChange` receives every widget's place after a drag or resize. */
export function mountDashboardGrid(
  element: HTMLElement,
  options: {
    editing: boolean;
    onChange: (layout: DashboardLayoutItem[]) => void;
  }
): DashboardGridController {
  const grid = GridStack.init(
    {
      column: DASHBOARD_COLUMNS,
      cellHeight: DASHBOARD_ROW_HEIGHT,
      margin: DASHBOARD_MARGIN,
      handle: "[data-dashboard-drag-handle]",
      animate: false,
      disableDrag: !options.editing,
      disableResize: !options.editing,
      resizable: { handles: "se" },
    },
    element
  );
  if (!grid) {
    throw new Error("gridstack could not start on the dashboard grid.");
  }
  let syncing = false;
  const report = () => {
    if (syncing) {
      return;
    }
    const layout: DashboardLayoutItem[] = [];
    for (const node of grid.engine.nodes) {
      if (node.id) {
        layout.push({
          widgetId: String(node.id),
          x: node.x ?? 0,
          y: node.y ?? 0,
          w: node.w ?? 1,
          h: node.h ?? 1,
        });
      }
    }
    options.onChange(layout);
  };
  grid.on("change", report);

  const sync = (layout: readonly DashboardLayoutItem[], editing: boolean) => {
    syncing = true;
    grid.batchUpdate();
    try {
      for (const node of [...grid.engine.nodes]) {
        if (node.el && node.el.parentElement !== element) {
          grid.removeWidget(node.el, false, false);
        }
      }
      for (const child of itemElements(element)) {
        const id = child.getAttribute("gs-id");
        const item = layout.find((entry) => entry.widgetId === id);
        if (item && !child.gridstackNode) {
          grid.makeWidget(child, { id: item.widgetId, ...place(item) });
        } else if (item && differs(child, item)) {
          grid.update(child, place(item));
        }
      }
    } finally {
      grid.batchUpdate(false);
      syncing = false;
    }
    grid.enableMove(editing);
    grid.enableResize(editing);
  };

  return {
    sync,
    destroy: () => {
      grid.offAll();
      grid.destroy(false);
    },
  };
}

/*
 * Dashboard grid, shared by the React and Vue editions. gridstack.js places
 * the widgets on desktop once loaded; until then (and when it cannot load)
 * these rules put them where the layout says. Phones stack them.
 */
.yayaw-dashboard-grid {
  --dashboard-columns: 4;
  position: relative;
  min-height: calc(var(--dashboard-rows, 1) * var(--dashboard-row-height));
}
.yayaw-dashboard-grid:not([data-grid-ready]) > .grid-stack-item {
  position: absolute;
  left: calc(var(--dashboard-x) * 100% / var(--dashboard-columns));
  top: calc(var(--dashboard-y) * var(--dashboard-row-height));
  width: calc(var(--dashboard-w) * 100% / var(--dashboard-columns));
  height: calc(var(--dashboard-h) * var(--dashboard-row-height));
}
.yayaw-dashboard-grid:not([data-grid-ready])
  > .grid-stack-item
  > .grid-stack-item-content {
  position: absolute;
  inset: var(--dashboard-margin);
}
.yayaw-dashboard-grid > .grid-stack-item > .grid-stack-item-content {
  overflow: visible;
}
.yayaw-dashboard-grid .grid-stack-placeholder > .placeholder-content {
  border: 2px dashed var(--ring, oklch(0.708 0 0));
  border-radius: calc(var(--radius, 0.625rem) + 2px);
  background: color-mix(
    in oklab,
    var(--muted, oklch(0.97 0 0)) 70%,
    transparent
  );
}
.yayaw-dashboard-grid > .grid-stack-item > .ui-resizable-se {
  right: calc(var(--dashboard-margin) + 2px);
  bottom: calc(var(--dashboard-margin) + 2px);
  border-radius: 4px;
  background-color: var(--background, oklch(1 0 0));
  opacity: 0.9;
}
.yayaw-dashboard-grid [data-dashboard-drag-handle] {
  cursor: grab;
  touch-action: none;
}
/* Phones: one column, each widget as tall as its rows by default. */
.yayaw-dashboard-stack {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: calc(var(--dashboard-margin) * 2);
}
.yayaw-dashboard-stack > [data-dashboard-item] {
  display: flex;
  min-width: 0;
  height: calc(
    var(--dashboard-h) *
    var(--dashboard-row-height) -
    var(--dashboard-margin) *
    2
  );
}
.yayaw-dashboard-stack > [data-dashboard-item] > * {
  flex: 1;
  min-width: 0;
}
/*
 * Rows are sized for a quarter of a desktop grid, not for a phone: figures,
 * notes and host blocks take the height of their content, charts one
 * proportional to the phone's width. Record widgets keep their rows, which
 * set how many they show.
 */
.yayaw-dashboard-stack
> [data-dashboard-item]:has(
  [data-widget-type="kpi"],
  [data-widget-type="note"],
  [data-widget-type="block"],
  [data-widget-mode="chart"]
) {
  height: auto;
}
.yayaw-dashboard-stack [data-widget-type="kpi"] > [data-widget-body],
.yayaw-dashboard-stack [data-widget-type="note"] > [data-widget-body],
.yayaw-dashboard-stack [data-widget-type="block"] > [data-widget-body] {
  flex: none;
  container-type: inline-size;
}
.yayaw-dashboard-stack
  [data-dashboard-widget]:has([data-widget-mode="chart"])
  > [data-widget-body] {
  flex: none;
  height: auto;
  min-height: 11rem;
  max-height: 20rem;
  aspect-ratio: 16 / 10;
}
/* Widgets line up with the toolbar despite their margins. */
[data-dashboard-layout="grid"] {
  margin-inline: calc(var(--dashboard-margin) * -1);
}

/*
 * Widget bodies are size containers: charts fill them (`100cqh`). They clip,
 * unless the widget asks to scroll (`settings.overflow: "scroll"`).
 */
[data-dashboard-widget] > [data-widget-body] {
  container-type: size;
  overflow: hidden;
}
[data-dashboard-widget] > [data-widget-body][data-overflow="scroll"] {
  overflow: auto;
}

/*
 * Flow sections: widgets one under the other, at full width and the height
 * of their content. Bodies grow with it (no size container, nothing clipped),
 * so records keep the view's pagination; charts take a 16:10 body, as on
 * phones, since they fill their container.
 */
.yayaw-dashboard-flow {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: calc(var(--dashboard-margin, 6px) * 2);
}
.yayaw-dashboard-flow > [data-dashboard-item] {
  display: flex;
  min-width: 0;
}
.yayaw-dashboard-flow > [data-dashboard-item] > * {
  flex: 1;
  min-width: 0;
}
.yayaw-dashboard-flow [data-dashboard-widget] > [data-widget-body] {
  container-type: inline-size;
  overflow: visible;
}
.yayaw-dashboard-flow
  [data-dashboard-widget]:has([data-widget-mode="chart"])
  > [data-widget-body] {
  container-type: size;
  height: auto;
  min-height: 11rem;
  max-height: 24rem;
  aspect-ratio: 16 / 10;
}

/* Fit: the records that do not fit are hidden (dashboard-fit.ts). */
[data-dashboard-fit] {
  display: flex;
  flex: 1 1 0%;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
[data-dashboard-fit] [data-dashboard-overflow] {
  display: none !important;
}
[data-dashboard-fit] [data-feed-footer] {
  display: none !important;
}
/* No space kept below the records for pagination or bulk actions. */
[data-dashboard-fit] [data-yayaw-table-selection-scope] > * {
  margin-block: 0;
}
/* Boards share the widget's width; lanes that do not fit are hidden. */
[data-dashboard-fit] [data-kanban-board],
[data-dashboard-fit] [data-kanban-board] > * {
  width: auto;
  min-width: 0;
  min-height: 0;
  grid-auto-columns: minmax(9rem, 1fr);
}
[data-dashboard-fit] [data-kanban-board] {
  overflow: hidden;
}
[data-dashboard-fit] [data-kanban-lane] {
  width: auto;
  min-width: 0;
  min-height: 0;
}

/* "+3 more · View all" under a fit widget's records. */
[data-widget-more] {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem 0.375rem;
  padding-top: 0.375rem;
  color: var(--yayaw-muted-foreground, var(--muted-foreground));
  font-size: 0.75rem;
  line-height: 1rem;
}
[data-widget-more] button {
  margin: 0;
  border: 0;
  border-radius: 0.25rem;
  background: none;
  padding: 0;
  color: var(--yayaw-foreground, var(--foreground));
  font: inherit;
  font-weight: 500;
  cursor: pointer;
}
[data-widget-more] button:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}
[data-widget-more] button:focus-visible {
  outline: 2px solid var(--yayaw-ring, var(--ring));
  outline-offset: 2px;
}

/* Numbers: a compact card, the title above the figure. */
[data-widget-type="kpi"] > [data-widget-header] {
  min-height: 0;
  border-bottom-width: 0;
  padding-bottom: 0;
}
[data-widget-type="kpi"] > [data-widget-header] [data-widget-title] {
  color: var(--yayaw-muted-foreground, var(--muted-foreground));
  font-size: 0.8125rem;
}
[data-widget-type="kpi"] > [data-widget-body] {
  padding-top: 0.125rem;
  padding-bottom: 0.625rem;
}
/* Figures start under the title, so the numbers of a row line up. */
[data-kpi] {
  display: flex;
  height: 100%;
  min-width: 0;
  flex-direction: column;
  justify-content: flex-start;
  gap: 0.125rem;
}
[data-kpi-main] {
  display: flex;
  min-width: 0;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.75rem;
}
[data-kpi-value] {
  display: block;
  min-width: 0;
  overflow: hidden;
  font-size: 1.75rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  line-height: 2rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
[data-kpi-trend] {
  display: block;
  width: min(42%, 7.5rem);
  height: 2rem;
  flex: none;
  overflow: visible;
  color: var(--yayaw-chart-1, var(--chart-1, currentColor));
}
[data-kpi-trend] polyline {
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
  vector-effect: non-scaling-stroke;
}
[data-kpi-compare] {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.25rem;
  margin: 0;
  overflow: hidden;
  color: var(--yayaw-muted-foreground, var(--muted-foreground));
  font-size: 0.75rem;
  line-height: 1rem;
  white-space: nowrap;
}
[data-kpi-compare] > span {
  overflow: hidden;
  text-overflow: ellipsis;
}
[data-kpi-compare] > svg {
  width: 0.875rem;
  height: 0.875rem;
  flex: none;
}
[data-kpi-compare][data-tone="positive"] {
  color: oklch(0.527 0.154 150.069);
}
[data-kpi-compare][data-tone="negative"] {
  color: var(--yayaw-danger, var(--destructive, oklch(0.577 0.245 27.325)));
}
.dark [data-kpi-compare][data-tone="positive"] {
  color: oklch(0.723 0.219 149.579);
}
[data-kpi-state] {
  margin: 0;
  color: var(--yayaw-muted-foreground, var(--muted-foreground));
  font-size: 0.75rem;
}
[data-kpi-state="error"] {
  color: var(--yayaw-danger, var(--destructive));
}

/*
 * A host block that renders nothing leaves no empty card in a flow (it stays
 * while editing, so it can be moved or removed); a grid keeps its card.
 */
[data-dashboard]:not([data-editing])
  .yayaw-dashboard-flow
  > [data-dashboard-item]:has(
    > [data-widget-type="block"] [data-block-content]:empty
  ) {
  display: none;
}

/* Full-page tables: no card; their body grows with the table. */
.yayaw-dashboard-flow [data-dashboard-widget][data-widget-frame="page"]
  > [data-widget-body] {
  container-type: normal;
  overflow: visible;
}

"use client";

import {
  type CSSProperties,
  type ReactNode,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { DashboardGridController } from "./dashboard-grid-engine";
import {
  DASHBOARD_MARGIN,
  DASHBOARD_ROW_HEIGHT,
  type DashboardLayoutItem,
  dashboardColumnsForWidth,
  layoutRows,
  stackLayout,
} from "./dashboard-layout";
import "./dashboard-grid.css";

// Layout effects measure before paint in the browser; the server skips them.
const useBrowserLayoutEffect =
  typeof window === "undefined" ? useEffect : useLayoutEffect;

const readingOrder = (a: DashboardLayoutItem, b: DashboardLayoutItem) =>
  a.y - b.y || a.x - b.x;

const gridVariables = (rows: number) =>
  ({
    "--dashboard-rows": rows,
    "--dashboard-row-height": `${DASHBOARD_ROW_HEIGHT}px`,
    "--dashboard-margin": `${DASHBOARD_MARGIN}px`,
  }) as CSSProperties;

const itemVariables = (item: DashboardLayoutItem) =>
  ({
    "--dashboard-x": item.x,
    "--dashboard-y": item.y,
    "--dashboard-w": item.w,
    "--dashboard-h": item.h,
  }) as CSSProperties;

export interface DashboardGridProps {
  layout: DashboardLayoutItem[];
  editing: boolean;
  onLayoutChange: (layout: DashboardLayoutItem[]) => void;
  renderItem: (widgetId: string, phone: boolean) => ReactNode;
}

/** Four columns with gridstack on desktop; one stacked column on phones. */
export function DashboardGrid(props: DashboardGridProps) {
  const container = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  useBrowserLayoutEffect(() => {
    const element = container.current;
    if (!element) {
      return;
    }
    setWidth(element.getBoundingClientRect().width);
    const observer = new ResizeObserver(([entry]) => {
      if (entry) {
        setWidth(entry.contentRect.width);
      }
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const phone = dashboardColumnsForWidth(width) === 1;
  return (
    <div
      data-dashboard-layout={phone ? "stack" : "grid"}
      ref={container}
      style={gridVariables(layoutRows(props.layout))}
    >
      {phone ? <StackedGrid {...props} /> : <DesktopGrid {...props} />}
    </div>
  );
}

function StackedGrid({ layout, renderItem }: DashboardGridProps) {
  return (
    <div className="yayaw-dashboard-stack">
      {stackLayout(layout).map((item) => (
        <div
          data-dashboard-item={item.widgetId}
          data-layout={`${item.x},${item.y},${item.w},${item.h}`}
          key={item.widgetId}
          style={itemVariables(item)}
        >
          {renderItem(item.widgetId, true)}
        </div>
      ))}
    </div>
  );
}

function DesktopGrid({
  editing,
  layout,
  onLayoutChange,
  renderItem,
}: DashboardGridProps) {
  const element = useRef<HTMLDivElement>(null);
  const controller = useRef<DashboardGridController | null>(null);
  const latest = useRef({ editing, layout, onLayoutChange });
  latest.current = { editing, layout, onLayoutChange };
  const [ready, setReady] = useState(false);
  const ordered = useMemo(() => [...layout].sort(readingOrder), [layout]);

  useEffect(() => {
    let cancelled = false;
    let mounted: DashboardGridController | undefined;
    // gridstack loads with the first desktop grid, not with the page.
    import("./dashboard-grid-engine")
      .then(({ mountDashboardGrid }) => {
        if (cancelled || !element.current) {
          return;
        }
        mounted = mountDashboardGrid(element.current, {
          editing: latest.current.editing,
          onChange: (next) => latest.current.onLayoutChange(next),
        });
        controller.current = mounted;
        mounted.sync(latest.current.layout, latest.current.editing);
        setReady(true);
      })
      .catch(() => {
        // Without gridstack, the CSS layout and the keyboard menu still work.
      });
    return () => {
      cancelled = true;
      controller.current = null;
      mounted?.destroy();
    };
  }, []);

  // After each render: new widgets join gridstack, moved ones take their place.
  useBrowserLayoutEffect(() => {
    controller.current?.sync(layout, editing);
  });

  return (
    <div
      className="grid-stack yayaw-dashboard-grid"
      data-editing={editing ? "" : undefined}
      data-grid-ready={ready ? "" : undefined}
      ref={element}
    >
      {ordered.map((item) => (
        <div
          className="grid-stack-item"
          data-dashboard-item={item.widgetId}
          data-layout={`${item.x},${item.y},${item.w},${item.h}`}
          gs-h={item.h}
          gs-id={item.widgetId}
          gs-w={item.w}
          gs-x={item.x}
          gs-y={item.y}
          key={item.widgetId}
          style={itemVariables(item)}
        >
          <div className="grid-stack-item-content">
            {renderItem(item.widgetId, false)}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  type DashboardColumn,
  type DashboardFilterValue,
  type DashboardStorage,
  type DashboardTableInfo,
  type DashboardView,
  type DashboardViewerFilters,
  dashboardColumn,
  loadDashboardViews,
  setDashboardViewerFilter,
} from "./dashboard-model";
import {
  canonicalDashboardJson,
  type Dashboard,
  type DashboardBlocks,
  normalizeDashboard,
} from "./dashboard-schema";
import {
  createDashboardSourceLoader,
  type DashboardSourceLoader,
  type DashboardSourceSummary,
  type DashboardSources,
} from "./dashboard-sources";
import {
  readDashboardUrlFilters,
  writeDashboardUrlFilters,
} from "./dashboard-url";
import type { DashboardTableSource } from "./dashboard-widget";

// Layout effects run before paint in the browser; the server skips them.
const useBrowserLayoutEffect =
  typeof window === "undefined" ? useEffect : useLayoutEffect;

export type DashboardLoadState =
  | { status: "loading" }
  | { status: "ready" }
  | { status: "empty" }
  | { status: "error"; message: string };

export const errorText = (error: unknown) =>
  error instanceof Error ? error.message : String(error);

/** What the dashboard knows of a loaded source: its name, columns and formats. */
export const tableInfo = (
  tableId: string,
  source: DashboardTableSource
): DashboardTableInfo => ({
  name: source.name ?? source.config.translations?.keys?.title ?? tableId,
  coloredTags: source.config.table.coloredTags,
  defaultDisplayMode: source.config.table.defaultDisplayMode,
  columns: source.config.columns.definitions.map((column) =>
    dashboardColumn(column as DashboardColumn)
  ),
});

/** A loaded source's summary, for the catalogue and reference checks. */
export const summarizeSource = (
  id: string,
  source: DashboardTableSource
): DashboardSourceSummary => ({
  id,
  name: tableInfo(id, source).name,
  columns: source.config.columns.definitions.map((column) => ({
    id: column.id,
    ...(typeof column.header === "string" ? { header: column.header } : {}),
    ...(column.type ? { type: String(column.type) } : {}),
  })),
  displayModes: [...(source.config.table.displayModes ?? ["table"])],
  views: (source.views ?? []).map((view) => ({
    id: view.id,
    name: view.name,
    ...(view.config.displayMode
      ? { displayMode: String(view.config.displayMode) }
      : {}),
  })),
});

type Provided = { dashboard: Dashboard } | { error: string } | undefined;

const readProvided = (input: unknown, blocks?: DashboardBlocks): Provided => {
  if (input === undefined) {
    return;
  }
  try {
    return { dashboard: normalizeDashboard(input, { blocks }) };
  } catch (error) {
    return { error: errorText(error) };
  }
};

const providedState = (provided: Provided): DashboardLoadState => {
  if (!provided) {
    return { status: "loading" };
  }
  return "error" in provided
    ? { status: "error", message: provided.error }
    : { status: "ready" };
};

/**
 * The document: `dashboard` when the host gives one (shown again when it
 * changes), else loaded from storage (`dashboardId`, else the first listed).
 * Documents are read with the host's blocks (misplaced blocks move).
 */
export function useDashboardDocument({
  blocks,
  dashboardId,
  input,
  storage,
}: {
  blocks?: DashboardBlocks;
  dashboardId?: string;
  input: unknown;
  storage?: DashboardStorage;
}) {
  const blocksRef = useRef(blocks);
  blocksRef.current = blocks;
  const provided = useMemo(
    () => readProvided(input, blocksRef.current),
    [input]
  );
  const [dashboard, setDashboard] = useState<Dashboard | undefined>(() =>
    provided && "dashboard" in provided ? provided.dashboard : undefined
  );
  const [state, setState] = useState<DashboardLoadState>(() =>
    providedState(provided)
  );
  // Equal documents keep the edits in progress.
  const shown = useRef(
    provided && "dashboard" in provided
      ? canonicalDashboardJson(provided.dashboard)
      : ""
  );
  useEffect(() => {
    if (!provided) {
      return;
    }
    if ("dashboard" in provided) {
      const json = canonicalDashboardJson(provided.dashboard);
      if (json !== shown.current) {
        shown.current = json;
        setDashboard(provided.dashboard);
      }
    }
    setState(providedState(provided));
  }, [provided]);
  const given = input !== undefined;
  useEffect(() => {
    if (given) {
      return;
    }
    if (!storage) {
      setState({ status: "empty" });
      return;
    }
    let cancelled = false;
    const load = async () => {
      const id = dashboardId ?? (await storage.list()).at(0)?.id;
      if (!id) {
        return;
      }
      return normalizeDashboard(await storage.load(id), {
        blocks: blocksRef.current,
      });
    };
    setState({ status: "loading" });
    load()
      .then((loaded) => {
        if (!cancelled) {
          setDashboard(loaded);
          setState({ status: loaded ? "ready" : "empty" });
        }
      })
      .catch((error: unknown) => {
        if (!cancelled) {
          setState({ status: "error", message: errorText(error) });
        }
      });
    return () => {
      cancelled = true;
    };
  }, [dashboardId, given, storage]);
  return { dashboard, setDashboard, state };
}

/**
 * The screen's sources: `tables` (ready at once, winning over the catalogue)
 * and the lazy `sources`, loaded only for the ids asked. Re-renders when a
 * source's state changes.
 */
export function useDashboardSources({
  ids,
  sources,
  tables,
}: {
  ids: readonly string[];
  sources?: DashboardSources<DashboardTableSource>;
  tables?: Record<string, DashboardTableSource>;
}): { loader: DashboardSourceLoader<DashboardTableSource>; version: number } {
  const loader = useMemo(
    () =>
      createDashboardSourceLoader<DashboardTableSource>({
        sources,
        tables,
        summarize: summarizeSource,
      }),
    [sources, tables]
  );
  const [version, setVersion] = useState(0);
  useEffect(
    () => loader.subscribe(() => setVersion((value) => value + 1)),
    [loader]
  );
  const key = ids.join("\n");
  useEffect(() => {
    for (const id of key ? key.split("\n") : []) {
      loader.load(id).catch(() => undefined);
    }
  }, [key, loader]);
  return { loader, version };
}

/**
 * Saved views of the sources asked, once each is ready (static views, then
 * `views.list`); a source loaded anew (new tables or catalogue) asks again.
 */
export function useSourceViews(
  loader: DashboardSourceLoader<DashboardTableSource>,
  ids: readonly string[]
) {
  const [views, setViews] = useState<
    Record<string, DashboardView[] | undefined>
  >({});
  const asked = useRef(new Map<string, DashboardTableSource>());
  // Which of them are ready changes with the loader's states (each re-renders).
  const ready = JSON.stringify(
    ids.filter((id) => loader.state(id)?.status === "ready")
  );
  useEffect(() => {
    for (const id of JSON.parse(ready) as string[]) {
      const state = loader.state(id);
      if (state?.status !== "ready" || asked.current.get(id) === state.source) {
        continue;
      }
      const source = state.source;
      asked.current.set(id, source);
      loadDashboardViews(source, id)
        .catch(() => loadDashboardViews({ views: source.views }, id))
        .then((loaded) => {
          if (asked.current.get(id) === source) {
            setViews((current) => ({ ...current, [id]: loaded }));
          }
        })
        .catch(() => undefined);
    }
  }, [loader, ready]);
  return views;
}

/**
 * The values a reader picks for the filters: view state, synced to the URL
 * (`<dashboardId>.<filterId>`) unless `syncUrl` is false, never written to
 * the document. `ready` once the URL was read (after mounting, as the server
 * has no URL), so widgets query once, with the reader's values.
 */
export function useViewerFilters(
  dashboard: Pick<Dashboard, "id" | "filters"> | undefined,
  syncUrl: boolean
) {
  const [values, setValues] = useState<DashboardViewerFilters>({});
  const [ready, setReady] = useState(!syncUrl);
  const latest = useRef(values);
  latest.current = values;
  const current = useRef(dashboard);
  current.current = dashboard;
  const shape = dashboard
    ? JSON.stringify([
        dashboard.id,
        dashboard.filters.map((filter) => [filter.id, filter.type]),
      ])
    : "";
  useBrowserLayoutEffect(() => {
    if (!(shape && syncUrl)) {
      setReady(true);
      return;
    }
    const readUrl = () => {
      const doc = current.current;
      if (doc) {
        setValues(readDashboardUrlFilters(doc));
      }
    };
    readUrl();
    setReady(true);
    window.addEventListener("popstate", readUrl);
    return () => window.removeEventListener("popstate", readUrl);
  }, [shape, syncUrl]);
  const write = useCallback(
    (next: DashboardViewerFilters) => {
      latest.current = next;
      setValues(next);
      const doc = current.current;
      if (syncUrl && doc) {
        writeDashboardUrlFilters(doc, next);
      }
    },
    [syncUrl]
  );
  const set = useCallback(
    (filterId: string, value: DashboardFilterValue | undefined) => {
      const doc = current.current;
      if (doc) {
        write(setDashboardViewerFilter(doc, latest.current, filterId, value));
      }
    },
    [write]
  );
  const clear = useCallback(() => write({}), [write]);
  return { values, set, clear, ready };
}

interface SourceRevision {
  /** "Refresh all" and refreshes of this source: every widget reloads. */
  refresh: number;
  /** Changes made in a page table: the source's other widgets reload. */
  mutation: number;
}

const MUTATION_DELAY = 150;

/**
 * When widgets load again: "Refresh all", a block's `refresh(tableId)`, and
 * changes made in a page table (grouped: an import or a bulk edit reloads
 * once).
 */
export function useDashboardRevisions() {
  const [revision, setRevision] = useState(0);
  const [sources, setSources] = useState<Record<string, SourceRevision>>({});
  const pending = useRef(new Set<string>());
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  const bump = useCallback(
    (ids: Iterable<string>, key: keyof SourceRevision) => {
      setSources((current) => {
        const next = { ...current };
        for (const id of ids) {
          const known = next[id] ?? { refresh: 0, mutation: 0 };
          next[id] = { ...known, [key]: known[key] + 1 };
        }
        return next;
      });
    },
    []
  );
  const refresh = useCallback(
    (tableId?: string) => {
      if (tableId) {
        bump([tableId], "refresh");
      } else {
        setRevision((value) => value + 1);
      }
    },
    [bump]
  );
  const mutated = useCallback(
    (tableId: string) => {
      pending.current.add(tableId);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => {
        const ids = [...pending.current];
        pending.current.clear();
        bump(ids, "mutation");
      }, MUTATION_DELAY);
    },
    [bump]
  );
  let total = 0;
  for (const entry of Object.values(sources)) {
    total += entry.refresh + entry.mutation;
  }
  return {
    revision,
    refresh,
    mutated,
    /** Numbers and views: "Refresh all", refreshes and changes of their source. */
    widgetRevision: (tableId?: string) => {
      const entry = tableId ? sources[tableId] : undefined;
      return revision + (entry ? entry.refresh + entry.mutation : 0);
    },
    /** Page tables: "Refresh all" and refreshes of their source (their own changes reload them already). */
    pageRevision: (tableId: string) =>
      revision + (sources[tableId]?.refresh ?? 0),
    /** Blocks: any of them. */
    blockRevision: revision + total,
  };
}

"use client";

import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import type { ChartColumn } from "@/components/ui/yayaw-table/utils/chart-model";
import {
  type Dashboard,
  type DashboardKpiPlan,
  type DashboardKpiResult,
  type DashboardNotice,
  type DashboardTranslate,
  type DashboardView,
  type DashboardWidget,
  dashboardDayValue,
  dashboardKpiDisplay,
  dashboardKpiPlan,
  dashboardViewParams,
  loadDashboardKpi,
  widgetViewConfig,
} from "./dashboard-model";
import {
  type DashboardLabel,
  type DashboardTableSource,
  WidgetNotice,
} from "./dashboard-widget";

type KpiState =
  | { status: "loading" }
  | { status: "ready"; result: DashboardKpiResult }
  | { status: "error"; message: string };

const TREND_ICONS = {
  up: ArrowUpRight,
  down: ArrowDownRight,
  flat: Minus,
};

export interface KpiWidgetProps {
  dashboard: Pick<Dashboard, "filters">;
  widget: DashboardWidget;
  source: DashboardTableSource;
  view?: DashboardView;
  /** Changes with "Refresh all": the numbers load again. */
  revision: number;
  locale: string;
  label: DashboardLabel;
  translate: DashboardTranslate;
  /** What a source's `meta.notice` says (`dashboardNoticeText`). */
  noticeText: (notice: DashboardNotice) => string;
}

type KpiContentProps = Omit<KpiWidgetProps, "revision"> & {
  onRetry: () => void;
};

function KpiContent({
  dashboard,
  label,
  locale,
  noticeText,
  onRetry,
  source,
  translate,
  view,
  widget,
}: KpiContentProps) {
  const columns = source.config.columns
    .definitions as unknown as readonly ChartColumn[];
  const [state, setState] = useState<KpiState>({ status: "loading" });
  // Periods end today; the plan changes (and loads again) with the day.
  const planKey = JSON.stringify(
    dashboardKpiPlan(dashboard, widget, dashboardDayValue(new Date()), columns)
  );
  const plan = useMemo(
    () => JSON.parse(planKey) as DashboardKpiPlan,
    [planKey]
  );
  // Inline settings, else the saved view's: its filters and search.
  const paramsKey = JSON.stringify(
    dashboardViewParams(widgetViewConfig(widget, view))
  );
  const { actions } = source;
  useEffect(() => {
    const controller = new AbortController();
    loadDashboardKpi({
      plan,
      actions: actions as Parameters<typeof loadDashboardKpi>[0]["actions"],
      params: JSON.parse(paramsKey) as Record<string, unknown>,
      locale,
      signal: controller.signal,
    })
      .then((result) => {
        if (!controller.signal.aborted) {
          setState({ status: "ready", result });
        }
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) {
          setState({
            status: "error",
            message: error instanceof Error ? error.message : String(error),
          });
        }
      });
    return () => controller.abort();
  }, [actions, locale, paramsKey, plan]);

  if (state.status === "error") {
    return (
      <div data-kpi="">
        <p data-kpi-state="error" role="alert">
          {label("widgetError", { error: state.message })}
        </p>
        <Button
          className="self-start"
          onClick={onRetry}
          size="xs"
          type="button"
          variant="outline"
        >
          {label("retry")}
        </Button>
      </div>
    );
  }
  if (state.status === "loading") {
    return (
      <div aria-busy="true" data-kpi="">
        <output data-kpi-state="loading">{label("widgetLoading")}</output>
      </div>
    );
  }
  if (state.result.notice) {
    return (
      <WidgetNotice kind="notice" reason={state.result.notice.code}>
        {noticeText(state.result.notice)}
      </WidgetNotice>
    );
  }
  const display = dashboardKpiDisplay({
    plan,
    result: state.result,
    columns,
    locale,
    translate,
  });
  const comparison = display.comparison;
  const TrendIcon = comparison ? TREND_ICONS[comparison.trend] : undefined;
  return (
    <div data-kpi="">
      <div data-kpi-main="">
        <output data-chart-number="" data-kpi-value="" title={display.caption}>
          {display.value}
        </output>
        {display.trend ? (
          <svg
            data-kpi-trend=""
            preserveAspectRatio="none"
            role="img"
            viewBox="0 0 100 32"
          >
            <title>{display.trend.title}</title>
            <polyline points={display.trend.points} />
          </svg>
        ) : null}
      </div>
      {comparison && TrendIcon ? (
        <p
          data-kpi-compare=""
          data-tone={comparison.tone}
          data-trend={comparison.trend}
          title={comparison.periods}
        >
          <TrendIcon aria-hidden="true" />
          <span>{comparison.text}</span>
        </p>
      ) : null}
    </div>
  );
}

/**
 * A number over a table or a view's records, in the column's format, with
 * its change against the previous period and a trend line when the widget
 * asks for them. Aggregated by the host (`aggregate`), else over `list`.
 */
export function KpiWidget({ revision, ...props }: KpiWidgetProps) {
  const [attempt, setAttempt] = useState(0);
  return (
    <KpiContent
      {...props}
      key={`${revision}:${attempt}`}
      onRetry={() => setAttempt((value) => value + 1)}
    />
  );
}

/**
 * Grid layouts of dashboard sections: widgets on a 4-column grid, placed,
 * repaired, moved and resized without overlaps (gridstack's top gravity).
 * Each grid section has its own layout. Pure and server-safe, shared by the
 * React and Vue editions (synced to Vue by `scripts/sync-table-contracts.mjs`).
 */

/** Widgets per row on desktop. */
export const DASHBOARD_COLUMNS = 4;
/** Tallest widget, in rows. */
export const DASHBOARD_MAX_HEIGHT = 12;
/** Height of one row, in pixels (the gaps are included). */
export const DASHBOARD_ROW_HEIGHT = 120;
/** Space around each widget, in pixels. */
export const DASHBOARD_MARGIN = 6;
/** Grids narrower than this (phones) stack widgets in one column, without drag. */
export const DASHBOARD_PHONE_MAX_WIDTH = 639;

export type DashboardDirection = "left" | "right" | "up" | "down";
export type DashboardResize = "wider" | "narrower" | "taller" | "shorter";

/** Where a widget sits: columns `x`…`x + w - 1`, rows `y`…`y + h - 1`. */
export interface DashboardLayoutItem {
  widgetId: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

const integer = (value: unknown, fallback: number): number => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.trunc(number) : fallback;
};
const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

/** Sizes of new widgets by type; views depend on their display mode. */
const DEFAULT_SIZES: Readonly<Record<string, { w: number; h: number }>> = {
  view: { w: 2, h: 2 },
  kpi: { w: 1, h: 1 },
  note: { w: 1, h: 2 },
  block: { w: 2, h: 2 },
};
const FALLBACK_SIZE = { w: 2, h: 2 };

/**
 * View widgets by display mode: records and charts take 2×2 (the default),
 * boards, galleries, calendars and feeds 2×3, file trees 1×3, Gantt charts
 * the whole width.
 */
const MODE_SIZES: Readonly<Record<string, { w: number; h: number }>> = {
  kanban: { w: 2, h: 3 },
  gallery: { w: 2, h: 3 },
  calendar: { w: 2, h: 3 },
  feed: { w: 2, h: 3 },
  form: { w: 2, h: 3 },
  filetree: { w: 1, h: 3 },
  gantt: { w: 4, h: 3 },
};

/** Size of a new widget of this type (and, for views, display mode). */
export const defaultWidgetSize = (
  type: string,
  mode?: string
): { w: number; h: number } => ({
  ...((type === "view" && mode ? MODE_SIZES[mode] : undefined) ??
    DEFAULT_SIZES[type] ??
    FALLBACK_SIZE),
});

/** Whole numbers inside the grid: `w` 1…columns, `h` 1…max, `x` keeps it inside. */
export function clampLayoutItem(
  item: DashboardLayoutItem,
  columns = DASHBOARD_COLUMNS
): DashboardLayoutItem {
  const w = clamp(integer(item.w, 1), 1, columns);
  return {
    widgetId: item.widgetId,
    x: clamp(integer(item.x, 0), 0, columns - w),
    y: Math.max(0, integer(item.y, 0)),
    w,
    h: clamp(integer(item.h, 1), 1, DASHBOARD_MAX_HEIGHT),
  };
}

const overlaps = (a: DashboardLayoutItem, b: DashboardLayoutItem): boolean =>
  a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

const readingOrder = (a: DashboardLayoutItem, b: DashboardLayoutItem) =>
  a.y - b.y || a.x - b.x;

/** Rows the layout takes. */
export const layoutRows = (layout: readonly DashboardLayoutItem[]): number =>
  layout.reduce((rows, item) => Math.max(rows, item.y + item.h), 0);

/** Moves each widget down until it overlaps none placed before it. */
function pushDown(
  items: readonly DashboardLayoutItem[]
): DashboardLayoutItem[] {
  const placed: DashboardLayoutItem[] = [];
  for (const item of items) {
    const next = { ...item };
    let blocker = placed.find((other) => overlaps(other, next));
    while (blocker) {
      next.y = blocker.y + blocker.h;
      blocker = placed.find((other) => overlaps(other, next));
    }
    placed.push(next);
  }
  return placed;
}

/** Top gravity, as gridstack's default mode: widgets rise into free space above them. */
export function compactLayout(
  layout: readonly DashboardLayoutItem[]
): DashboardLayoutItem[] {
  const placed: DashboardLayoutItem[] = [];
  for (const item of [...layout].sort(readingOrder)) {
    const next = { ...item };
    while (
      next.y > 0 &&
      !placed.some((other) => overlaps(other, { ...next, y: next.y - 1 }))
    ) {
      next.y -= 1;
    }
    placed.push(next);
  }
  return placed.sort(readingOrder);
}

/**
 * Resolves overlaps: `fixedId` (the widget just moved or resized) keeps its
 * place, the others move below what they overlap, then everything rises.
 */
export function resolveLayout(
  layout: readonly DashboardLayoutItem[],
  fixedId?: string,
  columns = DASHBOARD_COLUMNS
): DashboardLayoutItem[] {
  const items = layout.map((item) => clampLayoutItem(item, columns));
  const fixed = items.filter((item) => item.widgetId === fixedId);
  const others = items
    .filter((item) => item.widgetId !== fixedId)
    .sort(readingOrder);
  return compactLayout(pushDown([...fixed, ...others]));
}

/** First free place for a widget of this size, scanning rows then columns. */
export function findFreeSpot(
  layout: readonly DashboardLayoutItem[],
  size: { w: number; h: number },
  columns = DASHBOARD_COLUMNS
): { x: number; y: number } {
  const w = clamp(size.w, 1, columns);
  const rows = layoutRows(layout);
  for (let y = 0; y <= rows; y += 1) {
    for (let x = 0; x + w <= columns; x += 1) {
      const candidate = { widgetId: "", x, y, w, h: size.h };
      if (!layout.some((item) => overlaps(item, candidate))) {
        return { x, y };
      }
    }
  }
  return { x: 0, y: rows };
}

/**
 * The layout of these widgets: one item per widget (unknown items dropped,
 * missing widgets placed in the first free spot), inside the grid, without
 * overlaps and risen to the top.
 */
export function normalizeLayout(
  layout: readonly DashboardLayoutItem[],
  widgets: readonly { id: string; type: string }[],
  columns = DASHBOARD_COLUMNS
): DashboardLayoutItem[] {
  const known = new Set(widgets.map((widget) => widget.id));
  const seen = new Set<string>();
  const items: DashboardLayoutItem[] = [];
  for (const item of layout) {
    if (known.has(item.widgetId) && !seen.has(item.widgetId)) {
      seen.add(item.widgetId);
      items.push(clampLayoutItem(item, columns));
    }
  }
  let resolved = resolveLayout(items, undefined, columns);
  for (const widget of widgets) {
    if (!seen.has(widget.id)) {
      const size = defaultWidgetSize(widget.type);
      const spot = findFreeSpot(resolved, size, columns);
      resolved = resolveLayout(
        [...resolved, { widgetId: widget.id, ...spot, ...size }],
        widget.id,
        columns
      );
    }
  }
  return resolved;
}

const sameColumns = (a: DashboardLayoutItem, b: DashboardLayoutItem) =>
  a.x < b.x + b.w && b.x < a.x + a.w;
const sameRows = (a: DashboardLayoutItem, b: DashboardLayoutItem) =>
  a.y < b.y + b.h && b.y < a.y + a.h;

/** The nearest widget in a direction sharing the item's columns or rows. */
function neighbour(
  layout: readonly DashboardLayoutItem[],
  item: DashboardLayoutItem,
  direction: DashboardDirection
): DashboardLayoutItem | undefined {
  const others = layout.filter((other) => other.widgetId !== item.widgetId);
  const candidates: Record<DashboardDirection, () => DashboardLayoutItem[]> = {
    up: () =>
      others
        .filter((o) => sameColumns(o, item) && o.y + o.h <= item.y)
        .sort((a, b) => b.y + b.h - (a.y + a.h) || a.x - b.x),
    down: () =>
      others
        .filter((o) => sameColumns(o, item) && o.y >= item.y + item.h)
        .sort((a, b) => a.y - b.y || a.x - b.x),
    left: () =>
      others
        .filter((o) => sameRows(o, item) && o.x + o.w <= item.x)
        .sort((a, b) => b.x + b.w - (a.x + a.w) || a.y - b.y),
    right: () =>
      others
        .filter((o) => sameRows(o, item) && o.x >= item.x + item.w)
        .sort((a, b) => a.x - b.x || a.y - b.y),
  };
  return candidates[direction]().at(0);
}

const replaceItem = (
  layout: readonly DashboardLayoutItem[],
  ...changed: DashboardLayoutItem[]
): DashboardLayoutItem[] =>
  layout.map(
    (item) =>
      changed.find((next) => next.widgetId === item.widgetId) ?? { ...item }
  );

/** Left or right: swap with the adjacent widget when both fit, else one column. */
function moveSideways(
  layout: readonly DashboardLayoutItem[],
  item: DashboardLayoutItem,
  direction: "left" | "right",
  columns: number
): DashboardLayoutItem[] {
  const other = neighbour(layout, item, direction);
  const adjacent =
    other &&
    (direction === "left"
      ? other.x + other.w === item.x
      : item.x + item.w === other.x);
  if (other && adjacent) {
    const left = direction === "left" ? item : other;
    const right = direction === "left" ? other : item;
    const start = Math.min(item.x, other.x);
    const moved = [
      { ...left, x: start },
      { ...right, x: start + left.w },
    ];
    if (start + left.w + right.w <= columns) {
      return resolveLayout(replaceItem(layout, ...moved), item.widgetId);
    }
  }
  const x = item.x + (direction === "left" ? -1 : 1);
  return resolveLayout(
    replaceItem(layout, { ...item, x }),
    item.widgetId,
    columns
  );
}

/**
 * Keyboard alternative to dragging: up and down swap with the nearest widget
 * above or below, left and right with the adjacent one (or move a column).
 */
export function moveLayoutItem(
  layout: readonly DashboardLayoutItem[],
  widgetId: string,
  direction: DashboardDirection,
  columns = DASHBOARD_COLUMNS
): DashboardLayoutItem[] {
  const item = layout.find((entry) => entry.widgetId === widgetId);
  if (!(item && canMoveLayoutItem(layout, widgetId, direction, columns))) {
    return layout.map((entry) => ({ ...entry }));
  }
  if (direction === "left" || direction === "right") {
    return moveSideways(layout, item, direction, columns);
  }
  const other = neighbour(layout, item, direction);
  if (!other) {
    return layout.map((entry) => ({ ...entry }));
  }
  // Up: take the place of the widget above. Down: let the widget below rise
  // into this place and settle under it.
  const y = direction === "up" ? other.y : other.y + other.h;
  const moved = replaceItem(layout, { ...item, y });
  return direction === "up"
    ? resolveLayout(moved, item.widgetId, columns)
    : resolveLayout(moved, other.widgetId, columns);
}

/** Whether the widget can move that way (menus disable the others). */
export function canMoveLayoutItem(
  layout: readonly DashboardLayoutItem[],
  widgetId: string,
  direction: DashboardDirection,
  columns = DASHBOARD_COLUMNS
): boolean {
  const item = layout.find((entry) => entry.widgetId === widgetId);
  if (!item) {
    return false;
  }
  switch (direction) {
    case "left":
      return item.x > 0;
    case "right":
      return item.x + item.w < columns;
    case "up":
    case "down":
      return Boolean(neighbour(layout, item, direction));
    default:
      return false;
  }
}

const RESIZE_CHANGES: Record<DashboardResize, { w: number; h: number }> = {
  wider: { w: 1, h: 0 },
  narrower: { w: -1, h: 0 },
  taller: { w: 0, h: 1 },
  shorter: { w: 0, h: -1 },
};

/** Whether the widget can grow or shrink that way. */
export function canResizeLayoutItem(
  layout: readonly DashboardLayoutItem[],
  widgetId: string,
  change: DashboardResize,
  columns = DASHBOARD_COLUMNS
): boolean {
  const item = layout.find((entry) => entry.widgetId === widgetId);
  if (!item) {
    return false;
  }
  const { w, h } = RESIZE_CHANGES[change];
  const width = item.w + w;
  const height = item.h + h;
  return (
    width >= 1 &&
    width <= columns &&
    height >= 1 &&
    height <= DASHBOARD_MAX_HEIGHT
  );
}

/** Keyboard alternative to the resize handle; a wider widget moves left when it must. */
export function resizeLayoutItem(
  layout: readonly DashboardLayoutItem[],
  widgetId: string,
  change: DashboardResize,
  columns = DASHBOARD_COLUMNS
): DashboardLayoutItem[] {
  const item = layout.find((entry) => entry.widgetId === widgetId);
  if (!(item && canResizeLayoutItem(layout, widgetId, change, columns))) {
    return layout.map((entry) => ({ ...entry }));
  }
  const { w, h } = RESIZE_CHANGES[change];
  const width = item.w + w;
  const next = {
    ...item,
    w: width,
    h: item.h + h,
    x: Math.min(item.x, columns - width),
  };
  return resolveLayout(replaceItem(layout, next), widgetId, columns);
}

/** Columns for a grid this wide: one on phones, four otherwise. */
export const dashboardColumnsForWidth = (width: number): number =>
  width > 0 && width <= DASHBOARD_PHONE_MAX_WIDTH ? 1 : DASHBOARD_COLUMNS;

/** Phone layout: widgets in reading order, one per row, full width, same heights. */
export function stackLayout(
  layout: readonly DashboardLayoutItem[]
): DashboardLayoutItem[] {
  let y = 0;
  return [...layout].sort(readingOrder).map((item) => {
    const stacked = { ...item, x: 0, y, w: 1 };
    y += item.h;
    return stacked;
  });
}

/** Whether two layouts place the same widgets at the same places (in any order). */
export const sameLayout = (
  a: readonly DashboardLayoutItem[],
  b: readonly DashboardLayoutItem[]
): boolean =>
  a.length === b.length &&
  a.every((item) => {
    const other = b.find((entry) => entry.widgetId === item.widgetId);
    return (
      other &&
      other.x === item.x &&
      other.y === item.y &&
      other.w === item.w &&
      other.h === item.h
    );
  });

/**
 * Positions a grid section's gridstack reported after a drag or resize,
 * normalized; an unchanged layout keeps the same section object.
 */
export function applyGridLayout<
  T extends { layout: readonly DashboardLayoutItem[] },
>(section: T, items: readonly DashboardLayoutItem[]): T {
  const layout = normalizeLayout(
    section.layout.map(
      (item) => items.find((next) => next.widgetId === item.widgetId) ?? item
    ),
    section.layout.map((item) => ({ id: item.widgetId, type: "view" }))
  );
  return sameLayout(layout, section.layout) ? section : { ...section, layout };
}

