          <span className="ms-auto">
            <WidgetMenu
              canMove={canMove}
              canResize={canResize}
              label={label}
              onMove={onMove}
              onRemove={onRemove}
              onResize={onResize}
              resizable={false}
              title={title}
            />
          </span>
